/**
 * 인도네시아어 구어체 (듣기·알아듣기 중심), 1500장.
 * 후보 순위: OpenSubtitles2018 인도네시아어 단어 빈도표 (orgtre/top-open-subtitles-sentences, CC BY 3.0 코드 · 목록은 OpenSubtitles 코퍼스 조건).
 * 빈도표는 넣지 않았다. 자막은 번역문이라 kau·anda·adalah 같은 격식형이 많아서, 순위를 그대로 따르지 않고 실용성을 우선해 직접 골라 적었다.
 * - 1~100장: 인사·대명사·부정·질문·담화표지·생활 동사 순.
 * - 101~500장: 빈도순 (구어형은 표준형의 순위로 줄 세움, 빈도표에 없는 구어형·은어는 맨 뒤).
 * - 501~1000장: 같은 방식으로 다음 묶음 (각 묶음 안에서 빈도순, 묶음은 뒤에 이어 붙인다).
 * 이미 설치한 덱에는 뒤의 단어만 이어서 넣는다 (packAdditions). 순서를 바꾸거나 중간에 끼워 넣지 말고 뒤에 붙일 것.
 * 현지인 검증은 하지 않았다. 같은 내용을 Anki용 CSV로도 만들었다 (docs/decks/).
 */
function w(word: string, meaning: string, standard: string, root: string, example: string, exampleKo: string, register: string, note: string, tags: string[]): PackNote {
  // 영어 뜻 · 자주 쓰는 표현은 따로 적어 두고 여기서 붙인다 (indonesianColloquialExtra.ts)
  const [en = '', ...phrases] = EXTRA[word] ?? [];
  return { typeId: 'id-spoken', fields: { word, meaning, en, standard, root, example, exampleKo, phrases: phrases.join('\n'), register, note }, tags };
}

